function getCoursesByProgramme(programmeType, level, semester) {
  return ALL_FUEK_COURSES.filter(
    (c2) => c2.programmeType === programmeType && c2.level === level && (!semester || c2.semester === semester || c2.semester === "Both")
  );
}
function getCompulsoryCourses(programmeType, level, semester) {
  return getCoursesByProgramme(programmeType, level, semester).filter(
    (c2) => c2.type === "compulsory"
  );
}
function getElectiveCourses(programmeType, level, semester) {
  return getCoursesByProgramme(programmeType, level, semester).filter(
    (c2) => c2.type === "elective"
  );
}
function getGSTCourses(level) {
  return ALL_FUEK_COURSES.filter((c2) => c2.isGST && c2.level === level);
}
function getTotalCreditUnits(courses) {
  return courses.reduce((sum, c2) => sum + c2.creditUnits, 0);
}
function getScore(score) {
  if (score >= 70) return { grade: "A", gradePoint: 5 };
  if (score >= 60) return { grade: "B", gradePoint: 4 };
  if (score >= 50) return { grade: "C", gradePoint: 3 };
  if (score >= 45) return { grade: "D", gradePoint: 2 };
  if (score >= 40) return { grade: "E", gradePoint: 1 };
  return { grade: "F", gradePoint: 0 };
}
