function computeGPA$2(results, creditMap) {
  let totalPoints = 0;
  let totalUnits = 0;
  for (const r2 of results) {
    const units = creditMap[r2.courseCode] || 3;
    totalPoints += r2.gradePoint * units;
    totalUnits += units;
  }
  return totalUnits === 0 ? 0 : Math.round(totalPoints / totalUnits * 100) / 100;
}
function gradeFromScore(score) {
  if (score >= 70) return { grade: "A", gradePoint: 5 };
  if (score >= 60) return { grade: "B", gradePoint: 4 };
  if (score >= 50) return { grade: "C", gradePoint: 3 };
  if (score >= 45) return { grade: "D", gradePoint: 2 };
  if (score >= 40) return { grade: "E", gradePoint: 1 };
  return { grade: "F", gradePoint: 0 };
}
