function gradeFromTotalV6(score) {
  if (score >= 70) return { grade: "A", point: 5, remark: "Pass" };
  if (score >= 60) return { grade: "B", point: 4, remark: "Pass" };
  if (score >= 50) return { grade: "C", point: 3, remark: "Pass" };
  if (score >= 45) return { grade: "D", point: 2, remark: "Pass" };
  if (score >= 40) return { grade: "E", point: 1, remark: "Pass" };
  return { grade: "F", point: 0, remark: "Fail" };
}
function makeExamResult(id, courseCode, studentMatric, caTotal, examScore, semester, session, status, submittedAt, publishedAt) {
  const total = caTotal + examScore;
  const g2 = gradeFromTotalV6(total);
  return {
    id,
    courseCode,
    studentMatric,
    examScore,
    totalScore: total,
    grade: g2.grade,
    point: g2.point,
    remark: g2.remark,
    semester,
    session,
    status,
    submittedAt,
    publishedAt
  };
}
